import type { ProjectType } from '~/client';

interface ProjectTypeEntry {
  label: string;
}

// Key order defines the user-visible select order (Signature, Canvassing).
export const projectTypesConfig: Record<ProjectType, ProjectTypeEntry> = {
  signature: { label: 'Signature' },
  canvassing: { label: 'Canvassing' },
};

export function getProjectTypeLabel(type: ProjectType): string {
  return projectTypesConfig[type]?.label ?? snakeCaseToCapitalizedCase(type);
}

export const projectTypes: SelectItem<ProjectType>[] = Object.entries(projectTypesConfig).map(([value, { label }]) => ({
  value: value as ProjectType,
  name: label,
}));
