import type { ProjectStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

interface ProjectStatusEntry {
  label: string;
  variant: BadgeVariants;
}

// Key order defines the user-visible list order (Active, Draft, Completed, Removed).
export const projectStatusConfig: Record<ProjectStatus, ProjectStatusEntry> = {
  active: { label: 'Active', variant: 'success' },
  draft: { label: 'Draft', variant: 'default' },
  completed: { label: 'Completed', variant: 'info' },
  removed: { label: 'Removed', variant: 'destructive' },
};

const defaultProjectStatus: ProjectStatusEntry = { label: '', variant: 'default' };

export function getProjectStatus(status: ProjectStatus): ProjectStatusEntry {
  return projectStatusConfig[status] ?? { ...defaultProjectStatus, label: snakeCaseToCapitalizedCase(status) };
}

export const projectsStatus: SelectItem<ProjectStatus>[] = Object.entries(projectStatusConfig).map(
  ([value, { label }]) => ({ value: value as ProjectStatus, name: label })
);
